cat > /app/solve.py <<'EOF'
import mteb, numpy as np, inspect

REV = "7999e1d3359715c523056ef9478215996d62a620"
model = mteb.get_model("BAAI/bge-small-zh-v1.5", revision=REV)

docs = [l.rstrip("\n") for l in open("/app/data.txt", encoding="utf-8")]
docs = [d for d in docs if d.strip()]
query = "terminal-bench"

def enc(texts, kind):
    fn = model.encode
    params = inspect.signature(fn).parameters
    kw = {}
    if "task_name" in params:
        kw["task_name"] = "Retrieval"
    if "prompt_type" in params:
        try:
            from mteb.encoder_interface import PromptType
        except Exception:
            from mteb.abstasks.TaskMetadata import PromptType  # fallback
        kw["prompt_type"] = PromptType.query if kind == "query" else PromptType.passage
    try:
        return np.asarray(fn(texts, **kw))
    except TypeError:
        return np.asarray(fn(texts))

q = enc([query], "query")
d = enc(docs, "passage")
qn = q / np.linalg.norm(q, axis=1, keepdims=True)
dn = d / np.linalg.norm(d, axis=1, keepdims=True)
sims = (dn @ qn.T).ravel()
order = np.argsort(-sims)
for r, i in enumerate(order[:8], 1):
    print(r, round(float(sims[i]), 4), docs[i])
best = docs[order[4]]
open("/app/result.txt", "w", encoding="utf-8").write(best + "\n")
print("RESULT:", best)
EOF
cd /app && timeout 900 python solve.py
